const conf = readConfig();
const pRes = await probe("proxy");
const bRes = await probe("backend");
const uRes = await probe("configuredUpstream");
const match = conf.upstreamPort === conf.backendPort;
const statusMatch = pRes.status === bRes.status;
const out = {
  config: conf,
  proxy: pRes,
  backend: bRes,
  upstream: uRes,
  analysis: {
    upstreamPortMatchesBackendPort: match,
    finding: match ? "Upstream port aligns with backend port." : "Upstream port does not match backend port, likely causing routing failure."
  }
};
console.log(JSON.stringify(out));
